<template><div class="page-head"><div><h2>订单列表</h2><div class="muted">查询订单及支付状态</div></div></div><ElCard class="card"><div class="filters"><ElInput v-model="q.keyword" clearable placeholder="订单号、收货人、手机号" style="width:300px" @keyup.enter="load"/><ElSelect v-model="q.status" clearable placeholder="全部状态" style="width:170px"><ElOption v-for="x in statuses" :key="x.v" :label="x.n" :value="x.v"/></ElSelect><ElButton type="warning" @click="load">查询</ElButton></div><ElTable :data="rows" v-loading="loading"><ElTableColumn prop="orderNo" label="订单号" min-width="190"/><ElTableColumn prop="nickname" label="用户" width="130"/><ElTableColumn prop="receiverName" label="收货人" width="100"/><ElTableColumn prop="receiverPhone" label="手机号" width="135"/><ElTableColumn label="金额" width="110"><template #default="s"><span class="price">¥{{s.row.payAmountYuan}}</span></template></ElTableColumn><ElTableColumn prop="status" label="订单状态" width="140"/><ElTableColumn prop="paymentStatus" label="支付状态" width="110"/><ElTableColumn prop="createdAt" label="下单时间" width="180"/><ElTableColumn label="操作" width="90"><template #default="s"><ElButton link type="primary" @click="detail(s.row.orderId)">详情</ElButton></template></ElTableColumn></ElTable><ElPagination class="pager" background layout="total, prev, pager, next" :total="total" :page-size="20" v-model:current-page="q.page" @change="load"/></ElCard><ElDrawer v-model="show" title="订单详情" size="520px"><template v-if="current"><ElDescriptions :column="1" border><ElDescriptionsItem label="订单号">{{current.orderNo}}</ElDescriptionsItem><ElDescriptionsItem label="订单状态">{{current.status}}</ElDescriptionsItem><ElDescriptionsItem label="支付状态">{{current.paymentStatus}}</ElDescriptionsItem><ElDescriptionsItem label="收货信息">{{current.receiverName}} {{current.receiverPhone}}<br/>{{current.receiverAddress}}</ElDescriptionsItem><ElDescriptionsItem label="实付金额">¥{{current.payAmountYuan}}</ElDescriptionsItem><ElDescriptionsItem label="交易号">{{current.transactionId||'-'}}</ElDescriptionsItem></ElDescriptions><h3>商品明细</h3><ElTable :data="current.items"><ElTableColumn prop="productName" label="商品"/><ElTableColumn prop="skuName" label="规格"/><ElTableColumn prop="quantity" label="数量" width="70"/></ElTable></template></ElDrawer></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api}from'../api';const statuses=[{n:'待支付',v:'PENDING_PAYMENT'},{n:'已支付',v:'PAID'},{n:'处理中',v:'PROCESSING'},{n:'已发货',v:'SHIPPED'},{n:'已完成',v:'COMPLETED'},{n:'已取消',v:'CANCELLED'}],q=reactive({keyword:'',status:'',page:1,pageSize:20}),rows=ref<any[]>([]),total=ref(0),loading=ref(false),show=ref(false),current=ref<any>();async function load(){loading.value=true;try{const d:any=await api.orders(q);rows.value=d.records;total.value=d.total}finally{loading.value=false}}async function detail(id:string){current.value=await api.order(id);show.value=true}onMounted(load)</script><style scoped>.pager{justify-content:flex-end;margin-top:20px}</style>
